<?php if (!defined('ABSPATH')) { exit; }
$research = is_array($data['research'] ?? null) ? $data['research'] : [];
?>
<section class="research-section" id="investigacion" aria-labelledby="researchTitle"><div class="container research-grid"><div><p class="eyebrow">INVESTIGACIÓN Y COOPERACIÓN</p><h2 id="researchTitle"><?php echo esc_html($research['title_lead'] ?? ''); ?><?php if (trim((string) ($research['title_em'] ?? '')) !== '') : ?><br><?php echo esc_html($research['title_em']); ?><?php endif; ?></h2><p><?php echo esc_html($research['intro'] ?? ''); ?></p><?php if (!empty($research['link']['url'])) : ?><a class="text-link" href="<?php echo esc_url($research['link']['url']); ?>"><?php echo esc_html($research['link']['label'] ?? ''); ?> <span aria-hidden="true">↗</span></a><?php endif; ?></div><div class="research-links"><?php foreach (array_slice((array) ($research['links'] ?? []), 0, 3) as $i => $item) : ?><a href="<?php echo esc_url($item['url'] ?? ''); ?>"><span><?php echo esc_html(sprintf('%02d', $i + 1)); ?></span> <?php echo esc_html($item['label'] ?? ''); ?> <b aria-hidden="true">↗</b></a><?php endforeach; ?></div></div></section>
